//go:build windows
package main
import("os";"encoding/json";"syscall";"unsafe";"time";"fmt";"os/exec";"context";"strings";"encoding/base64";"encoding/binary";"unicode/utf16")
func invoke(dll,name string,args ...uintptr)uintptr{v,_,_:=syscall.NewLazyDLL(dll).NewProc(name).Call(args...);return v}
type ft struct{Low,High uint32};func(f ft)num()uint64{return uint64(f.High)<<32|uint64(f.Low)}
func cpu()string{sample:=func()(uint64,uint64){idle,kernel,user:=new(ft),new(ft),new(ft);r,_,_:=syscall.NewLazyDLL("kernel32.dll").NewProc("GetSystemTimes").Call(uintptr(unsafe.Pointer(idle)),uintptr(unsafe.Pointer(kernel)),uintptr(unsafe.Pointer(user)));if r==0{return 0,0};return idle.num(),kernel.num()+user.num()};i,t:=sample();time.Sleep(200*time.Millisecond);ii,tt:=sample();if tt<=t{return "unavailable"};return fmt.Sprintf("%.1f",100*(1-float64(ii-i)/float64(tt-t)))}
func main(){var q struct{Op string `json:"op"`;Settings map[string]bool `json:"settings"`};if json.NewDecoder(os.Stdin).Decode(&q)!=nil{return};values:=map[string]string{};if q.Settings["cpu"]{values["cpu"]=cpu()};if q.Settings["ram"]{mem:=new(struct{Length,Load uint32;TotalPhys,AvailPhys,TotalPage,AvailPage,TotalVirtual,AvailVirtual,AvailExtended uint64});mem.Length=uint32(unsafe.Sizeof(*mem));r,_,_:=syscall.NewLazyDLL("kernel32.dll").NewProc("GlobalMemoryStatusEx").Call(uintptr(unsafe.Pointer(mem)));if r!=0{values["ram"]=fmt.Sprint(mem.Load)}else{values["ram"]="unavailable"}};if q.Settings["keyboard"]{var pid uint32;h:=invoke("user32.dll","GetForegroundWindow");thread,_,_:=syscall.NewLazyDLL("user32.dll").NewProc("GetWindowThreadProcessId").Call(h,uintptr(unsafe.Pointer(&pid)));layout:=invoke("user32.dll","GetKeyboardLayout",thread);buf:=make([]uint16,85);r,_,_:=syscall.NewLazyDLL("kernel32.dll").NewProc("LCIDToLocaleName").Call(layout&0xffff,uintptr(unsafe.Pointer(&buf[0])),85,0);if r!=0{values["keyboard"]=syscall.UTF16ToString(buf)}else{values["keyboard"]="unavailable"}};if q.Settings["gpu"]{script:=`[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false);try{$rows=Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine -ErrorAction Stop;$groups=$rows|Group-Object {($_.Name -split '_engtype_')[-1]};$max=0;foreach($g in $groups){$sum=($g.Group|Measure-Object UtilizationPercentage -Sum).Sum;if($sum -gt $max){$max=$sum}};if(-not $rows){'unavailable'}else{[Math]::Min(100,$max)}}catch{'unavailable'}`;units:=utf16.Encode([]rune(script));raw:=make([]byte,len(units)*2);for i,u:=range units{binary.LittleEndian.PutUint16(raw[i*2:],u)};ctx,cancel:=context.WithTimeout(context.Background(),3*time.Second);cmd:=exec.CommandContext(ctx,"powershell.exe","-NoProfile","-NonInteractive","-EncodedCommand",base64.StdEncoding.EncodeToString(raw));cmd.SysProcAttr=&syscall.SysProcAttr{HideWindow:true};b,e:=cmd.Output();cancel();if e==nil{values["gpu"]=strings.TrimSpace(string(b))}else{values["gpu"]="unavailable"}};json.NewEncoder(os.Stdout).Encode(map[string]any{"ok":true,"variables":values})}
